function income(shares, price, yieldPct){ shares=+shares; price=+price; yieldPct=+yieldPct;
  return Math.round(shares*price*(yieldPct/100)*100)/100; }
function yieldPct(shares, price, annualDiv){ shares=+shares; price=+price; annualDiv=+annualDiv;
  if(!(shares*price>0)) return {error:'市值须为正'}; return Math.round(annualDiv/(shares*price)*10000)/100; }
function quarterly(annual){ return Math.round(annual/4*100)/100; }
var EXPORTS={income:income, yieldPct:yieldPct, quarterly:quarterly};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DividendForgePure = EXPORTS; }
